.claude/sessions/07a0cb52-0445-49f9-8c0a-e19caebdf96d.jsonl:9:{"parentUuid":"7f859277-eb29-4461-bbe7-14f3116105d9","isSidechain":false,"promptId":"5c90884a-20ca-45eb-9499-bb098aee9682","type":"user","message":{"role":"user","content":[{"tool_use_id":"call_00_mlOW4yfi4XIhXnkBZWYb7447","type":"tool_result","content":"1\t#!/usr/bin/env bash\n2\t# agent-sync — single-file cross-machine sync for coding agents.\n3\t#\n4\t# Syncs memory / sessions / skills across machines for coding agents:\n5\t#   claude   (Claude Code)        sessions + auto-memory -> snapshot into .claude/sessions/\n6\t#   opencode (opencode)           sessions -> export/import into .opencode/sessions/ + `oc` wrapper\n7\t#   codex    (Codex CLI)          sessions -> copy filtered by cwd; memories/skills -> snapshot\n8\t#   dsh      (DeepSeek Harness)   sessions -> snapshot into .dsh/sessions/\n9\t#\n10\t# Usage (copy this file into your project root, then run):\n11\t#   ./setup.sh                              show this help (no args -> help)\n12\t#   ./setup.sh claude [opencode] [codex] [dsh]  init any combination of tools\n13\t#   ./setup.sh all                          init all four\n14\t#   ./setup.sh sync                         collect latest agent data (run BEFORE git commit+push)\n15\t#   ./setup.sh oc                           wrapper: launch opencode, then export sessions to git\n16\t#   ./setup.sh --help                       this help\n17\t#\n18\t# Idempotent: safe to re-run. Never writes API keys.\n19\t#\n20\t# PRIVACY: session transcripts record everything you type (including API keys).\n21\t# Use a PRIVATE repo for this project while developing; don't push the synced\n22\t# .claude/sessions, .opencode/sessions, .codex/sessions or .dsh/sessions to a public repo.\n23\tset -euo pipefail\n24\t\n25\tPROJECT=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\n26\tchmod +x \"$0\" 2>/dev/null || true\n27\t\n28\tinfo() { printf '==> %s\\n' \"$*\"; }\n29\tok()   { printf '    [ok] %s\\n' \"$*\"; }\n30\twarn() { printf '    [!!] %s\\n' \"$*\" >&2; }\n31\t\n32\tusage() {\n33\t  awk 'NR>1 && /^#/ {sub(/^# ?/,\"\"); print; next} NR>1 {exit}' \"$0\"\n34\t}\n35\t\n36\t# --- helpers ----------------------------------------------------------------\n37\t\n38\t# The encoded project path Claude Code uses as its per-project storage dir name.\n39\tencoded() { printf '%s' \"$PROJECT\" | sed 's|[^A-Za-z0-9]|-|g'; }\n40\t\n41\t# Copy files from $src into $dst that are missing or newer than the copy in\n42\t# $dst (merge by mtime). macOS cp has no -u, so compare mtimes manually.\n43\t_merge_newer() {  # $1 = source dir, $2 = dest dir\n44\t  local src=\"$1\" dst=\"$2\" f rel\n45\t  [ -d \"$src\" ] || return 0\n46\t  while IFS= read -r -d '' f; do\n47\t    rel=\"${f#\"$src\"/}\"\n48\t    if [ \"$f\" -nt \"$dst/$rel\" ]; then\n49\t      mkdir -p \"$(dirname \"$dst/$rel\")\"\n50\t      cp -p \"$f\" \"$dst/$rel\"\n51\t    fi\n52\t  done < <(find \"$src\" -type f -print0 2>/dev/null)\n53\t}\n54\t\n55\t# Snapshot a tool's native/global dir into the project (no symlink — the tool\n56\t# keeps working exactly as before). Merges by mtime both ways: newer files win\n57\t# in each direction, so a session continued on another machine is picked up and\n58\t# a locally-updated session is captured.\n59\tsnapshot_dir() {  # $1 = native/global dir, $2 = project dir\n60\t  local g=\"$1\" p=\"$2\"\n61\t  mkdir -p \"$g\" \"$p\"\n62\t  _merge_newer \"$p\" \"$g\"   # project -> native (newer wins)\n63\t  _merge_newer \"$g\" \"$p\"   # native -> project (newer wins)\n64\t  ok \"snapshot synced: $p\"\n65\t}\n66\t\n67\t# Idempotent cwd-aware `oc` wrapper: finds the nearest agent-sync project from\n68\t# $PWD (via the .agent-sync marker) and runs its setup.sh oc. No single global\n69\t# alias fighting over which project it points to.\n70\twrite_oc_func() {\n71\t  local zshrc=\"$HOME/.zshrc\"\n72\t  touch \"$zshrc\"\n73\t  python3 - \"$zshrc\" <<'PYEOF'\n74\timport re, sys\n75\tpath = sys.argv[1]\n76\ts = open(path).read()\n77\ts = re.sub(r'^alias oc=.*\\n', '', s, flags=re.M)\n78\ts = re.sub(r'^# agent-sync: oc alias\\n', '', s, flags=re.M)\n79\ts = re.sub(r'^# >>> agent-sync: oc >>>\\n.*?^# <<< agent-sync: oc <<<\\n', '', s, flags=re.M | re.S)\n80\tblock = (\n81\t    '# >>> agent-sync: oc >>>\\n'\n82\t    'unalias oc 2>/dev/null || true\\n'\n83\t    'oc() {\\n'\n84\t    '  local p=\"$PWD\"\\n'\n85\t    '  while [ \"$p\" != \"/\" ]; do\\n'\n86\t    '    if [ -f \"$p/.agent-sync\" ]; then\\n'\n87\t    '      bash \"$p/setup.sh\" oc \"$@\"; return $?\\n'\n88\t    '    fi\\n'\n89\t    '    p=\"$(dirname \"$p\")\"\\n'\n90\t    '  done\\n'\n91\t    '  echo \"oc: not in an agent-sync project (run setup.sh first)\" >&2\\n'\n92\t    '  return 1\\n'\n93\t    '}\\n'\n94\t    '# <<< agent-sync: oc <<<\\n'\n95\t)\n96\ts = s.rstrip() + \"\\n\\n\" + block\n97\topen(path, 'w').write(s)\n98\tPYEOF\n99\t  ok \"wrote cwd-aware oc() to ~/.zshrc  (run 'source ~/.zshrc' to activate)\"\n100\t}\n101\t\n102\t# Create a dir with a one-line README so git tracks it even when empty.\n103\tseed_dir() {  # $1 = dir, $2 = description\n104\t  local dir=\"$1\" desc=\"$2\"\n105\t  mkdir -p \"$dir\"\n106\t  if [ ! -f \"$dir/README.md\" ]; then\n107\t    printf '# %s (agent-sync)\\n\\n%s\\n' \"$(basename \"$dir\")\" \"$desc\" > \"$dir/README.md\"\n108\t    ok \"created $dir/\"\n109\t  else\n110\t    ok \"$dir/ already exists\"\n111\t  fi\n112\t}\n113\t\n114\t# --- claude -----------------------------------------------------------------\n115\t\n116\tinit_claude() {\n117\t  info \"claude (Claude Code)\"\n118\t  seed_dir \"$PROJECT/.claude/sessions\" \"Claude Code session transcripts + auto-memory (snapshot from ~/.claude/projects/<encoded>).\"\n119\t  seed_dir \"$PROJECT/.claude/skills\"   \"Shared skills; auto-loaded by Claude Code, referenced by opencode via skills.paths.\"\n120\t  seed_dir \"$PROJECT/.claude/memory\"   \"Long-lived project notes; git-tracked.\"\n121\t  snapshot_dir \"$HOME/.claude/projects/$(encoded)\" \"$PROJECT/.claude/sessions\"\n122\t}\n123\t\n124\t# --- opencode ---------------------------------------------------------------\n125\t\n126\tinit_opencode() {\n127\t  info \"opencode\"\n128\t  seed_dir \"$PROJECT/.opencode/sessions\" \"Exported opencode sessions (JSON). Auto-exported by the oc alias after each run.\"\n129\t  if ! command -v opencode >/dev/null 2>&1; then\n130\t    warn \"opencode not installed (brew install opencode-ai); skipping import\"\n131\t  else\n132\t    local db=\"${OPENCODE_DB:-$HOME/.local/share/opencode/opencode.db}\" n=0 meta id updated db_updated\n133\t    for f in \"$PROJECT\"/.opencode/sessions/*.json; do\n134\t      [ -e \"$f\" ] || continue\n135\t      meta=\"$(python3 -c 'import json,sys;d=json.load(open(sys.argv[1]));i=d.get(\"info\",{});print(i.get(\"id\",\"\"),i.get(\"time\",{}).get(\"updated\",0))' \"$f\" 2>/dev/null || true)\"\n136\t      id=\"${meta%% *}\"; updated=\"${meta##* }\"\n137\t      if [ -z \"$id\" ]; then warn \"no id in $(basename \"$f\")\"; continue; fi\n138\t      if [ -f \"$db\" ]; then\n139\t        db_updated=\"$(sqlite3 \"$db\" \"SELECT time_updated FROM session WHERE id='$id';\" 2>/dev/null | head -1)\"\n140\t        if [ -n \"$db_updated\" ] && [ \"$db_updated\" -ge \"$updated\" ] 2>/dev/null; then\n141\t          ok \"skip up-to-date session $id\"; continue\n142\t        fi\n143\t      fi\n144\t      if opencode import \"$f\" >/dev/null 2>&1; then\n145\t        ok \"imported session $id\"; n=$((n+1))\n146\t      else\n147\t        warn \"import failed: $(basename \"$f\")\"\n148\t      fi\n149\t    done\n150\t    info \"  imported $n opencode session(s)\"\n151\t  fi\n152\t  touch \"$PROJECT/.agent-sync\"\n153\t  write_oc_func\n154\t}\n155\t\n156\t# --- codex ------------------------------------------------------------------\n157\t\n158\tinit_codex() {\n159\t  info \"codex (Codex CLI)\"\n160\t  seed_dir \"$PROJECT/.codex/sessions\"  \"Codex CLI sessions for THIS project only (filtered by cwd).\"\n161\t  seed_dir \"$PROJECT/.codex/memories\"  \"Snapshot of global ~/.codex/memories.\"\n162\t  seed_dir \"$PROJECT/.codex/skills\"    \"Snapshot of global ~/.codex/skills (bundled .system/ gitignored).\"\n163\t\n164\t  # memories + skills are global per-user; snapshot them (no symlink, no competition).\n165\t  snapshot_dir \"$HOME/.codex/memories\" \"$PROJECT/.codex/memories\"\n166\t  snapshot_dir \"$HOME/.codex/skills\"   \"$PROJECT/.codex/skills\"\n167\t  if [ ! -f \"$PROJECT/.codex/skills/.gitignore\" ]; then\n168\t    printf '.system/\\n' > \"$PROJECT/.codex/skills/.gitignore\"\n169\t    ok \"gitignored .codex/skills/.system/\"\n170\t  fi\n171\t\n172\t  # sessions: codex stores them globally (not per-project), so filter by cwd\n173\t  # and COPY only this project's rollouts into the repo.\n174\t  sync_codex_sessions\n175\t}\n176\t\n177\t# Print the cwd recorded in a rollout's session_meta line (empty if none).\n178\tcodex_rollout_cwd() {  # $1 = rollout jsonl path\n179\t  python3 - \"$1\" <<'PYEOF'\n180\timport json, sys\n181\tcwd = \"\"\n182\tfor line in open(sys.argv[1], errors=\"replace\"):\n183\t    if '\"session_meta\"' not in line:\n184\t        continue\n185\t    try:\n186\t        d = json.loads(line)\n187\t    except Exception:\n188\t        continue\n189\t    if d.get(\"type\") == \"session_meta\":\n190\t        cwd = d.get(\"payload\", {}).get(\"cwd\") or \"\"\n191\t        break\n192\tprint(cwd)\n193\tPYEOF\n194\t}\n195\t\n196\tsync_codex_sessions() {\n197\t  local src=\"$HOME/.codex/sessions\" dst=\"$PROJECT/.codex/sessions\" n=0 cwd rel\n198\t  if [ -L \"$src\" ]; then\n199\t    warn \"~/.codex/sessions is a symlink (left by an old agent-sync); restore it, then re-run\"\n200\t    return 0\n201\t  fi\n202\t  mkdir -p \"$src\" \"$dst\"\n203\t  # restore: project -> native, preserving codex's date-based layout\n204\t  # (YYYY/MM/DD/). codex re-indexes by scanning ~/.codex/sessions on startup,\n205\t  # so no manual sqlite work is needed.\n206\t  _merge_newer \"$dst\" \"$src\"\n207\t  # sync: native -> project, preserving the date-based layout. Capture a rollout\n208\t  # if it's already known to this project (a session continued on another machine\n209\t  # keeps its original cwd), or a brand-new local session whose cwd matches.\n210\t  while IFS= read -r f; do\n211\t    rel=\"${f#\"$src\"/}\"\n212\t    if ! [ -e \"$dst/$rel\" ]; then\n213\t      cwd=\"$(codex_rollout_cwd \"$f\")\"\n214\t      if [ -z \"$cwd\" ] || ([ \"$cwd\" != \"$PROJECT\" ] && [[ \"$cwd\" != \"$PROJECT/\"* ]]); then\n215\t        continue\n216\t      fi\n217\t    fi\n218\t    if [ \"$f\" -nt \"$dst/$rel\" ]; then\n219\t      mkdir -p \"$(dirname \"$dst/$rel\")\"\n220\t      cp -p \"$f\" \"$dst/$rel\"\n221\t      n=$((n+1))\n222\t    fi\n223\t  done < <(find -L \"$src\" -name 'rollout-*.jsonl' 2>/dev/null)\n224\t  ok \"copied $n codex session(s) for this project (re-run to pick up new ones)\"\n225\t}\n226\t\n227\t# --- dsh (DeepSeek Harness) -------------------------------------------------\n228\t\n229\t# Encode a project path into dsh's per-project session directory key\n230\t# (mirrors projectKey() in dsh-session-persistence-jsonl).\n231\tdsh_project_key() {\n232\t  python3 - \"$PROJECT\" <<'PYEOF'\n233\timport sys\n234\tcwd = sys.argv[1]\n235\treadable = \"\"\n236\tseparator_run = False\n237\tfor ch in cwd:\n238\t    if ch in \"/\\\\:\":\n239\t        if not separator_run:\n240\t            readable += \"-\"\n241\t        separator_run = True\n242\t    elif ch != \"~\" and ((\"a\" <= ch <= \"z\") or (\"A\" <= ch <= \"Z\") or (\"0\" <= ch <= \"9\") or ch in \"._-\"):\n243\t        readable += ch\n244\t        separator_run = False\n245\t    else:\n246\t        readable += \"~\" + format(ord(ch), \"04X\")\n247\t        separator_run = False\n248\tkey = readable.lstrip(\"-\") or \"root\"\n249\tprint(\"--\" + key[:251] + \"--\")\n250\tPYEOF\n251\t}\n252\t\n253\tinit_dsh() {\n254\t  info \"dsh (DeepSeek Harness)\"\n255\t  seed_dir \"$PROJECT/.dsh/sessions\" \"dsh session transcripts (snapshot from ~/.dsh/sessions/<projectKey>).\"\n256\t  snapshot_dir \"$HOME/.dsh/sessions/$(dsh_project_key)\" \"$PROJECT/.dsh/sessions\"\n257\t}\n258\t\n259\t# --- sync -------------------------------------------------------------------\n260\t\n261\t# Collect the latest agent data before you commit + push. Snapshots are\n262\t# non-invasive copies of each tool's native storage. No git commands run here —\n263\t# commit + push manually afterwards.\n264\tsync_all() {\n265\t  info \"sync (collect latest agent data)\"\n266\t  snapshot_dir \"$HOME/.claude/projects/$(encoded)\" \"$PROJECT/.claude/sessions\"\n267\t  snapshot_dir \"$HOME/.dsh/sessions/$(dsh_project_key)\" \"$PROJECT/.dsh/sessions\"\n268\t  snapshot_dir \"$HOME/.codex/memories\" \"$PROJECT/.codex/memories\"\n269\t  snapshot_dir \"$HOME/.codex/skills\"   \"$PROJECT/.codex/skills\"\n270\t  sync_codex_sessions\n271\t  info \"opencode sessions export on exit via 'oc' — nothing to collect here.\"\n272\t  echo\n273\t  info \"now commit + push manually to sync across machines:\"\n274\t  info \"  git add .claude .opencode .codex .dsh && git commit -m 'sync agent data' && git push\"\n275\t}\n276\t\n277\t# --- oc launcher ------------------------------------------------------------\n278\t\n279\trun_oc() {\n280\t  cd \"$PROJECT\"\n281\t  # Single source of truth for the key: env first, then ~/.claude/settings.json.\n282\t  if [ -z \"${ANTHROPIC_AUTH_TOKEN:-}\" ]; then\n283\t    ANTHROPIC_AUTH_TOKEN=\"$(python3 -c 'import json,os;p=os.path.expanduser(\"~/.claude/settings.json\");d=json.load(open(p)) if os.path.exists(p) else {};print(d.get(\"env\",{}).get(\"ANTHROPIC_AUTH_TOKEN\",\"\"))' 2>/dev/null || true)\"\n284\t  fi\n285\t  export ANTHROPIC_AUTH_TOKEN\n286\t\n287\t  case \"${1:-}\" in\n288\t    run|serve|web|attach|export|import|models|session|agent|db|plugin|mcp|acp|stats|github|pr|upgrade|uninstall|completion|debug|providers|auth)\n289\t      opencode \"$@\" || true ;;\n290\t    *)\n291\t      opencode --auto \"$@\" || true ;;\n292\t  esac\n293\t\n294\t  local db=\"$HOME/.local/share/opencode/opencode.db\" sess_dir=\"$PROJECT/.opencode/sessions\" count=0 id\n295\t  mkdir -p \"$sess_dir\"\n296\t  if [ ! -f \"$db\" ]; then\n297\t    warn \"no opencode db found; nothing exported\"; return 0\n298\t  fi\n299\t  local ids\n300\t  ids=\"$(sqlite3 \"$db\" \"SELECT id FROM session WHERE (directory = '$PROJECT' OR directory LIKE '$PROJECT/%') AND parent_id IS NULL ORDER BY time_updated DESC;\")\"\n301\t  for id in $ids; do\n302\t    if opencode export \"$id\" 2>/dev/null > \"$sess_dir/$id.json\" && [ -s \"$sess_dir/$id.json\" ]; then\n303\t      count=$((count+1))\n304\t    else\n305\t      warn \"export failed for session $id\"\n306\t    fi\n307\t  done\n308\t  if [ \"$count\" -gt 0 ]; then\n309\t    git add \"$sess_dir\" 2>/dev/null || true\n310\t    if [ \"${OC_AUTOCOMMIT:-0}\" = \"1\" ]; then\n311\t      git commit -m \"sync opencode sessions ($(date +%F))\" 2>/dev/null || true\n312\t      ok \"exported + committed $count session(s)\"\n313\t    else\n314\t      ok \"exported $count session(s) -> .opencode/sessions/ (staged; set OC_AUTOCOMMIT=1 to auto-commit)\"\n315\t    fi\n316\t  else\n317\t    info \"no opencode sessions to export\"\n318\t  fi\n319\t}\n320\t\n321\t# --- dispatch ---------------------------------------------------------------\n322\t\n323\tif [ $# -eq 0 ]; then\n324\t  usage; exit 0\n325\tfi\n326\t\n327\tcase \"${1:-}\" in\n328\t  --help|-h|help) usage; exit 0 ;;\n329\t  oc) shift; run_oc \"$@\"; exit 0 ;;\n330\t  sync) sync_all; exit 0 ;;\n331\tesac\n332\t\n333\tfor a in \"$@\"; do\n334\t  case \"$a\" in\n335\t    claude)   init_claude ;;\n336\t    opencode) init_opencode ;;\n337\t    codex)    init_codex ;;\n338\t    dsh)      init_dsh ;;\n339\t    all)      init_claude; init_opencode; init_codex; init_dsh ;;\n340\t    *) warn \"unknown tool: $a\"; usage; exit 1 ;;\n341\t  esac\n342\tdone\n343\t\n344\techo\n345\tinfo \"done. 完成。\"\n346\tinfo \"usage / 用法:\"\n347\tinfo \"  claude / codex / dsh  -> 直接运行 (run directly)\"\n348\tinfo \"  opencode        -> 用 'oc' 运行,不要跑 opencode，需要做一层包装 (use 'oc', NOT bare 'opencode')\"\n349\tinfo \"  keep this repo PRIVATE while developing / 开发期请用私有仓库 — 待开发完成后删除跨级共享session\""}]},"uuid":"eb4f93ff-b007-476e-a3a4-33e7e242c2d9","timestamp":"2026-08-14T05:30:50.801Z","toolUseResult":{"type":"text","file":{"filePath":"/Users/marshall/Projects/DLToolKit/setup.sh","content":"#!/usr/bin/env bash\n# agent-sync — single-file cross-machine sync for coding agents.\n#\n# Syncs memory / sessions / skills across machines for coding agents:\n#   claude   (Claude Code)        sessions + auto-memory -> snapshot into .claude/sessions/\n#   opencode (opencode)           sessions -> export/import into .opencode/sessions/ + `oc` wrapper\n#   codex    (Codex CLI)          sessions -> copy filtered by cwd; memories/skills -> snapshot\n#   dsh      (DeepSeek Harness)   sessions -> snapshot into .dsh/sessions/\n#\n# Usage (copy this file into your project root, then run):\n#   ./setup.sh                              show this help (no args -> help)\n#   ./setup.sh claude [opencode] [codex] [dsh]  init any combination of tools\n#   ./setup.sh all                          init all four\n#   ./setup.sh sync                         collect latest agent data (run BEFORE git commit+push)\n#   ./setup.sh oc                           wrapper: launch opencode, then export sessions to git\n#   ./setup.sh --help                       this help\n#\n# Idempotent: safe to re-run. Never writes API keys.\n#\n# PRIVACY: session transcripts record everything you type (including API keys).\n# Use a PRIVATE repo for this project while developing; don't push the synced\n# .claude/sessions, .opencode/sessions, .codex/sessions or .dsh/sessions to a public repo.\nset -euo pipefail\n\nPROJECT=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nchmod +x \"$0\" 2>/dev/null || true\n\ninfo() { printf '==> %s\\n' \"$*\"; }\nok()   { printf '    [ok] %s\\n' \"$*\"; }\nwarn() { printf '    [!!] %s\\n' \"$*\" >&2; }\n\nusage() {\n  awk 'NR>1 && /^#/ {sub(/^# ?/,\"\"); print; next} NR>1 {exit}' \"$0\"\n}\n\n# --- helpers ----------------------------------------------------------------\n\n# The encoded project path Claude Code uses as its per-project storage dir name.\nencoded() { printf '%s' \"$PROJECT\" | sed 's|[^A-Za-z0-9]|-|g'; }\n\n# Copy files from $src into $dst that are missing or newer than the copy in\n# $dst (merge by mtime). macOS cp has no -u, so compare mtimes manually.\n_merge_newer() {  # $1 = source dir, $2 = dest dir\n  local src=\"$1\" dst=\"$2\" f rel\n  [ -d \"$src\" ] || return 0\n  while IFS= read -r -d '' f; do\n    rel=\"${f#\"$src\"/}\"\n    if [ \"$f\" -nt \"$dst/$rel\" ]; then\n      mkdir -p \"$(dirname \"$dst/$rel\")\"\n      cp -p \"$f\" \"$dst/$rel\"\n    fi\n  done < <(find \"$src\" -type f -print0 2>/dev/null)\n}\n\n# Snapshot a tool's native/global dir into the project (no symlink — the tool\n# keeps working exactly as before). Merges by mtime both ways: newer files win\n# in each direction, so a session continued on another machine is picked up and\n# a locally-updated session is captured.\nsnapshot_dir() {  # $1 = native/global dir, $2 = project dir\n  local g=\"$1\" p=\"$2\"\n  mkdir -p \"$g\" \"$p\"\n  _merge_newer \"$p\" \"$g\"   # project -> native (newer wins)\n  _merge_newer \"$g\" \"$p\"   # native -> project (newer wins)\n  ok \"snapshot synced: $p\"\n}\n\n# Idempotent cwd-aware `oc` wrapper: finds the nearest agent-sync project from\n# $PWD (via the .agent-sync marker) and runs its setup.sh oc. No single global\n# alias fighting over which project it points to.\nwrite_oc_func() {\n  local zshrc=\"$HOME/.zshrc\"\n  touch \"$zshrc\"\n  python3 - \"$zshrc\" <<'PYEOF'\nimport re, sys\npath = sys.argv[1]\ns = open(path).read()\ns = re.sub(r'^alias oc=.*\\n', '', s, flags=re.M)\ns = re.sub(r'^# agent-sync: oc alias\\n', '', s, flags=re.M)\ns = re.sub(r'^# >>> agent-sync: oc >>>\\n.*?^# <<< agent-sync: oc <<<\\n', '', s, flags=re.M | re.S)\nblock = (\n    '# >>> agent-sync: oc >>>\\n'\n    'unalias oc 2>/dev/null || true\\n'\n    'oc() {\\n'\n    '  local p=\"$PWD\"\\n'\n    '  while [ \"$p\" != \"/\" ]; do\\n'\n    '    if [ -f \"$p/.agent-sync\" ]; then\\n'\n    '      bash \"$p/setup.sh\" oc \"$@\"; return $?\\n'\n    '    fi\\n'\n    '    p=\"$(dirname \"$p\")\"\\n'\n    '  done\\n'\n    '  echo \"oc: not in an agent-sync project (run setup.sh first)\" >&2\\n'\n    '  return 1\\n'\n    '}\\n'\n    '# <<< agent-sync: oc <<<\\n'\n)\ns = s.rstrip() + \"\\n\\n\" + block\nopen(path, 'w').write(s)\nPYEOF\n  ok \"wrote cwd-aware oc() to ~/.zshrc  (run 'source ~/.zshrc' to activate)\"\n}\n\n# Create a dir with a one-line README so git tracks it even when empty.\nseed_dir() {  # $1 = dir, $2 = description\n  local dir=\"$1\" desc=\"$2\"\n  mkdir -p \"$dir\"\n  if [ ! -f \"$dir/README.md\" ]; then\n    printf '# %s (agent-sync)\\n\\n%s\\n' \"$(basename \"$dir\")\" \"$desc\" > \"$dir/README.md\"\n    ok \"created $dir/\"\n  else\n    ok \"$dir/ already exists\"\n  fi\n}\n\n# --- claude -----------------------------------------------------------------\n\ninit_claude() {\n  info \"claude (Claude Code)\"\n  seed_dir \"$PROJECT/.claude/sessions\" \"Claude Code session transcripts + auto-memory (snapshot from ~/.claude/projects/<encoded>).\"\n  seed_dir \"$PROJECT/.claude/skills\"   \"Shared skills; auto-loaded by Claude Code, referenced by opencode via skills.paths.\"\n  seed_dir \"$PROJECT/.claude/memory\"   \"Long-lived project notes; git-tracked.\"\n  snapshot_dir \"$HOME/.claude/projects/$(encoded)\" \"$PROJECT/.claude/sessions\"\n}\n\n# --- opencode ---------------------------------------------------------------\n\ninit_opencode() {\n  info \"opencode\"\n  seed_dir \"$PROJECT/.opencode/sessions\" \"Exported opencode sessions (JSON). Auto-exported by the oc alias after each run.\"\n  if ! command -v opencode >/dev/null 2>&1; then\n    warn \"opencode not installed (brew install opencode-ai); skipping import\"\n  else\n    local db=\"${OPENCODE_DB:-$HOME/.local/share/opencode/opencode.db}\" n=0 meta id updated db_updated\n    for f in \"$PROJECT\"/.opencode/sessions/*.json; do\n      [ -e \"$f\" ] || continue\n      meta=\"$(python3 -c 'import json,sys;d=json.load(open(sys.argv[1]));i=d.get(\"info\",{});print(i.get(\"id\",\"\"),i.get(\"time\",{}).get(\"updated\",0))' \"$f\" 2>/dev/null || true)\"\n      id=\"${meta%% *}\"; updated=\"${meta##* }\"\n      if [ -z \"$id\" ]; then warn \"no id in $(basename \"$f\")\"; continue; fi\n      if [ -f \"$db\" ]; then\n        db_updated=\"$(sqlite3 \"$db\" \"SELECT time_updated FROM session WHERE id='$id';\" 2>/dev/null | head -1)\"\n        if [ -n \"$db_updated\" ] && [ \"$db_updated\" -ge \"$updated\" ] 2>/dev/null; then\n          ok \"skip up-to-date session $id\"; continue\n        fi\n      fi\n      if opencode import \"$f\" >/dev/null 2>&1; then\n        ok \"imported session $id\"; n=$((n+1))\n      else\n        warn \"import failed: $(basename \"$f\")\"\n      fi\n    done\n    info \"  imported $n opencode session(s)\"\n  fi\n  touch \"$PROJECT/.agent-sync\"\n  write_oc_func\n}\n\n# --- codex ------------------------------------------------------------------\n\ninit_codex() {\n  info \"codex (Codex CLI)\"\n  seed_dir \"$PROJECT/.codex/sessions\"  \"Codex CLI sessions for THIS project only (filtered by cwd).\"\n  seed_dir \"$PROJECT/.codex/memories\"  \"Snapshot of global ~/.codex/memories.\"\n  seed_dir \"$PROJECT/.codex/skills\"    \"Snapshot of global ~/.codex/skills (bundled .system/ gitignored).\"\n\n  # memories + skills are global per-user; snapshot them (no symlink, no competition).\n  snapshot_dir \"$HOME/.codex/memories\" \"$PROJECT/.codex/memories\"\n  snapshot_dir \"$HOME/.codex/skills\"   \"$PROJECT/.codex/skills\"\n  if [ ! -f \"$PROJECT/.codex/skills/.gitignore\" ]; then\n    printf '.system/\\n' > \"$PROJECT/.codex/skills/.gitignore\"\n    ok \"gitignored .codex/skills/.system/\"\n  fi\n\n  # sessions: codex stores them globally (not per-project), so filter by cwd\n  # and COPY only this project's rollouts into the repo.\n  sync_codex_sessions\n}\n\n# Print the cwd recorded in a rollout's session_meta line (empty if none).\ncodex_rollout_cwd() {  # $1 = rollout jsonl path\n  python3 - \"$1\" <<'PYEOF'\nimport json, sys\ncwd = \"\"\nfor line in open(sys.argv[1], errors=\"replace\"):\n    if '\"session_meta\"' not in line:\n        continue\n    try:\n        d = json.loads(line)\n    except Exception:\n        continue\n    if d.get(\"type\") == \"session_meta\":\n        cwd = d.get(\"payload\", {}).get(\"cwd\") or \"\"\n        break\nprint(cwd)\nPYEOF\n}\n\nsync_codex_sessions() {\n  local src=\"$HOME/.codex/sessions\" dst=\"$PROJECT/.codex/sessions\" n=0 cwd rel\n  if [ -L \"$src\" ]; then\n    warn \"~/.codex/sessions is a symlink (left by an old agent-sync); restore it, then re-run\"\n    return 0\n  fi\n  mkdir -p \"$src\" \"$dst\"\n  # restore: project -> native, preserving codex's date-based layout\n  # (YYYY/MM/DD/). codex re-indexes by scanning ~/.codex/sessions on startup,\n  # so no manual sqlite work is needed.\n  _merge_newer \"$dst\" \"$src\"\n  # sync: native -> project, preserving the date-based layout. Capture a rollout\n  # if it's already known to this project (a session continued on another machine\n  # keeps its original cwd), or a brand-new local session whose cwd matches.\n  while IFS= read -r f; do\n    rel=\"${f#\"$src\"/}\"\n    if ! [ -e \"$dst/$rel\" ]; then\n      cwd=\"$(codex_rollout_cwd \"$f\")\"\n      if [ -z \"$cwd\" ] || ([ \"$cwd\" != \"$PROJECT\" ] && [[ \"$cwd\" != \"$PROJECT/\"* ]]); then\n        continue\n      fi\n    fi\n    if [ \"$f\" -nt \"$dst/$rel\" ]; then\n      mkdir -p \"$(dirname \"$dst/$rel\")\"\n      cp -p \"$f\" \"$dst/$rel\"\n      n=$((n+1))\n    fi\n  done < <(find -L \"$src\" -name 'rollout-*.jsonl' 2>/dev/null)\n  ok \"copied $n codex session(s) for this project (re-run to pick up new ones)\"\n}\n\n# --- dsh (DeepSeek Harness) -------------------------------------------------\n\n# Encode a project path into dsh's per-project session directory key\n# (mirrors projectKey() in dsh-session-persistence-jsonl).\ndsh_project_key() {\n  python3 - \"$PROJECT\" <<'PYEOF'\nimport sys\ncwd = sys.argv[1]\nreadable = \"\"\nseparator_run = False\nfor ch in cwd:\n    if ch in \"/\\\\:\":\n        if not separator_run:\n            readable += \"-\"\n        separator_run = True\n    elif ch != \"~\" and ((\"a\" <= ch <= \"z\") or (\"A\" <= ch <= \"Z\") or (\"0\" <= ch <= \"9\") or ch in \"._-\"):\n        readable += ch\n        separator_run = False\n    else:\n        readable += \"~\" + format(ord(ch), \"04X\")\n        separator_run = False\nkey = readable.lstrip(\"-\") or \"root\"\nprint(\"--\" + key[:251] + \"--\")\nPYEOF\n}\n\ninit_dsh() {\n  info \"dsh (DeepSeek Harness)\"\n  seed_dir \"$PROJECT/.dsh/sessions\" \"dsh session transcripts (snapshot from ~/.dsh/sessions/<projectKey>).\"\n  snapshot_dir \"$HOME/.dsh/sessions/$(dsh_project_key)\" \"$PROJECT/.dsh/sessions\"\n}\n\n# --- sync -------------------------------------------------------------------\n\n# Collect the latest agent data before you commit + push. Snapshots are\n# non-invasive copies of each tool's native storage. No git commands run here —\n# commit + push manually afterwards.\nsync_all() {\n  info \"sync (collect latest agent data)\"\n  snapshot_dir \"$HOME/.claude/projects/$(encoded)\" \"$PROJECT/.claude/sessions\"\n  snapshot_dir \"$HOME/.dsh/sessions/$(dsh_project_key)\" \"$PROJECT/.dsh/sessions\"\n  snapshot_dir \"$HOME/.codex/memories\" \"$PROJECT/.codex/memories\"\n  snapshot_dir \"$HOME/.codex/skills\"   \"$PROJECT/.codex/skills\"\n  sync_codex_sessions\n  info \"opencode sessions export on exit via 'oc' — nothing to collect here.\"\n  echo\n  info \"now commit + push manually to sync across machines:\"\n  info \"  git add .claude .opencode .codex .dsh && git commit -m 'sync agent data' && git push\"\n}\n\n# --- oc launcher ------------------------------------------------------------\n\nrun_oc() {\n  cd \"$PROJECT\"\n  # Single source of truth for the key: env first, then ~/.claude/settings.json.\n  if [ -z \"${ANTHROPIC_AUTH_TOKEN:-}\" ]; then\n    ANTHROPIC_AUTH_TOKEN=\"$(python3 -c 'import json,os;p=os.path.expanduser(\"~/.claude/settings.json\");d=json.load(open(p)) if os.path.exists(p) else {};print(d.get(\"env\",{}).get(\"ANTHROPIC_AUTH_TOKEN\",\"\"))' 2>/dev/null || true)\"\n  fi\n  export ANTHROPIC_AUTH_TOKEN\n\n  case \"${1:-}\" in\n    run|serve|web|attach|export|import|models|session|agent|db|plugin|mcp|acp|stats|github|pr|upgrade|uninstall|completion|debug|providers|auth)\n      opencode \"$@\" || true ;;\n    *)\n      opencode --auto \"$@\" || true ;;\n  esac\n\n  local db=\"$HOME/.local/share/opencode/opencode.db\" sess_dir=\"$PROJECT/.opencode/sessions\" count=0 id\n  mkdir -p \"$sess_dir\"\n  if [ ! -f \"$db\" ]; then\n    warn \"no opencode db found; nothing exported\"; return 0\n  fi\n  local ids\n  ids=\"$(sqlite3 \"$db\" \"SELECT id FROM session WHERE (directory = '$PROJECT' OR directory LIKE '$PROJECT/%') AND parent_id IS NULL ORDER BY time_updated DESC;\")\"\n  for id in $ids; do\n    if opencode export \"$id\" 2>/dev/null > \"$sess_dir/$id.json\" && [ -s \"$sess_dir/$id.json\" ]; then\n      count=$((count+1))\n    else\n      warn \"export failed for session $id\"\n    fi\n  done\n  if [ \"$count\" -gt 0 ]; then\n    git add \"$sess_dir\" 2>/dev/null || true\n    if [ \"${OC_AUTOCOMMIT:-0}\" = \"1\" ]; then\n      git commit -m \"sync opencode sessions ($(date +%F))\" 2>/dev/null || true\n      ok \"exported + committed $count session(s)\"\n    else\n      ok \"exported $count session(s) -> .opencode/sessions/ (staged; set OC_AUTOCOMMIT=1 to auto-commit)\"\n    fi\n  else\n    info \"no opencode sessions to export\"\n  fi\n}\n\n# --- dispatch ---------------------------------------------------------------\n\nif [ $# -eq 0 ]; then\n  usage; exit 0\nfi\n\ncase \"${1:-}\" in\n  --help|-h|help) usage; exit 0 ;;\n  oc) shift; run_oc \"$@\"; exit 0 ;;\n  sync) sync_all; exit 0 ;;\nesac\n\nfor a in \"$@\"; do\n  case \"$a\" in\n    claude)   init_claude ;;\n    opencode) init_opencode ;;\n    codex)    init_codex ;;\n    dsh)      init_dsh ;;\n    all)      init_claude; init_opencode; init_codex; init_dsh ;;\n    *) warn \"unknown tool: $a\"; usage; exit 1 ;;\n  esac\ndone\n\necho\ninfo \"done. 完成。\"\ninfo \"usage / 用法:\"\ninfo \"  claude / codex / dsh  -> 直接运行 (run directly)\"\ninfo \"  opencode        -> 用 'oc' 运行,不要跑 opencode，需要做一层包装 (use 'oc', NOT bare 'opencode')\"\ninfo \"  keep this repo PRIVATE while developing / 开发期请用私有仓库 — 待开发完成后删除跨级共享session\"","numLines":349,"startLine":1,"totalLines":349}},"sourceToolAssistantUUID":"7f859277-eb29-4461-bbe7-14f3116105d9","userType":"external","entrypoint":"cli","cwd":"/Users/marshall/Projects/DLToolKit","sessionId":"07a0cb52-0445-49f9-8c0a-e19caebdf96d","version":"2.1.126","gitBranch":"dev"}
